 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  ServerMessage,
 55→  ServerMessageHistory,
 56→  ServerTaskList,
 57→  ServerTaskUpdated,
 58→  ServerTaskDeleted,
 59→  Task,
 60→  TaskPriority,
