104→            disabled={!!resolved}
105→            onClick={() => toggle(i)}
106→            className={cn(
107→              "rounded-md border px-3 py-1.5 text-xs transition-colors",
108→              selected.has(i)
109→                ? "border-primary bg-primary text-primary-foreground"
110→                : "border-muted-foreground/30 bg-secondary hover:border-primary/50",
111→              resolved && "opacity-60 cursor-default"
112→            )}
113→            title={opt.description}
114→          >
115→            {opt.label}
116→            {opt.description && (
117→              <span className="ml-1 text-[10px] opacity-70">
118→                — {opt.description}
119→              </span>
120→            )}
121→          </button>
122→        ))}
123→      </div>
124→      {!resolved ? (
125→        <Button
126→          size="sm"
127→          disabled={selected.size === 0}
128→          onClick={handleSubmit}
129→        >
